import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const m=JSON.parse('{"title":"Week 2 — Ship Your Page","description":"","frontmatter":{"source":"weeks/02-ship-your-page/README.md"},"headers":[],"relativePath":"weeks/02-ship-your-page/index.md","filePath":"weeks/02-ship-your-page/index.md"}'),s={name:"weeks/02-ship-your-page/index.md"};function i(n,e,h,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="week-2--ship-your-page" tabindex="-1">Week 2 — Ship Your Page <a class="header-anchor" href="#week-2--ship-your-page" aria-label="Permalink to &quot;Week 2 — Ship Your Page&quot;">​</a></h1><blockquote><p>Publishing turns your page into something other people use, so it has to work for everyone, and you should be able to show how you made it.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (30 min)</td><td>Have your week 1 <code>index.html</code> with you (or download it from Canvas). Check you can sign in to GitHub on your laptop; bring your phone for two-factor authentication. Read this page</td></tr><tr><td><strong>Studio A</strong></td><td>Concept talk: from a file to a URL, commits, what public means, <code>PROMPTS.md</code>. Then publish your page on GitHub Pages and start <code>PROMPTS.md</code></td></tr><tr><td><strong>Studio B</strong></td><td>Practice the three habits on a new section, check your live page&#39;s accessibility, write your personal AI-use rules (🔴 AI off, on Canvas). Exit ticket</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before)</td><td>Your page live at <code>https://[your-username].github.io</code> with a <strong>Projects</strong> section · 5+ commits this week with clear messages · <code>PROMPTS.md</code> with 5+ entries · on Canvas (the course&#39;s learning management system, not Gemini&#39;s Canvas tool): your AI-use rules v1, your AI Fluency response and your reflection. Full list: <a href="./homework.html#deliverables-checklist">deliverables checklist</a></td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: improving your page, the accessibility review, formatting <code>PROMPTS.md</code> · 🟡 AI limited: none this week · 🔴 AI off: your AI-use rules, the Ownership statement in <code>PROMPTS.md</code>, at least one change by hand, the AI Fluency response, the exit ticket and the reflection</td></tr><tr><td><strong>Must read</strong></td><td>This page, the <a href="./lab.html">lab</a>, the <a href="./homework.html">homework</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../setup/github-basics.html">GitHub basics</a> · <a href="./../01-hello-vibe-coding/prompt-starters.html">Week 1 prompt starters</a> · <a href="./../../resources/prompt-patterns.html">Prompt Patterns</a> · <a href="./../../resources/web-basics.html">How the Web Works</a> · <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a> · <a href="./../../resources/troubleshooting.html">Troubleshooting</a> · <a href="./../../resources/glossary.html">Glossary</a> · <a href="./../../TOOLS.html">Tool Handout</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Your page is live at <code>https://[your-username].github.io</code> with a Projects section. Week 3&#39;s game goes into the same repository</td></tr><tr><td><strong>Time</strong></td><td>Studios 2½ h · outside about 6 h (prep up to 30 min, homework core about 5 h including project time, <code>PROMPTS.md</code> and the reflection); stretch is optional</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Explain how a file becomes a web page at a URL, and why it&#39;s called <code>index.html</code>.</li><li>Publish a page on GitHub Pages and update it with commits that have clear messages.</li><li>Use the three habits: ask me questions first, show a reference, say what works.</li><li>Check a page for basic accessibility problems (keyboard, zoom, contrast, structure) and fix them.</li><li>Keep a <code>PROMPTS.md</code> log that separates what the AI did from what you did.</li><li>Write your own rules for when you will and won&#39;t use AI.</li><li>Connect two of the four AI fluency skills to your own work.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Finish the <a href="./../01-hello-vibe-coding/homework.html">week 1 homework</a>. Have your latest <code>index.html</code> on the laptop you bring (or download it from Canvas in class).</li><li>☐ Check that you can sign in to github.com on that laptop. Bring your phone: GitHub asks for your second factor on a new browser.</li><li>☐ Read this page (10 minutes). If the GitHub website is new to you, skim <a href="./../../setup/github-basics.html">GitHub basics</a>.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap of week 1&#39;s most-missed exit-ticket question · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-02.html" target="_blank" rel="noreferrer">slides</a>): from your screen to the world, commits, public means public, <code>PROMPTS.md</code> · live demo: publishing a page · lab: publish on GitHub Pages, start <code>PROMPTS.md</code> · checkpoint share: open a neighbor&#39;s page on your phone</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Gallery walk of everyone&#39;s live page · lab: the three habits, an accessibility check, your personal AI-use rules (🔴 AI off) · exit ticket (🔴 AI off)</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="./lab.html">Lab</a></td><td>Step-by-step, both studios (must read)</td></tr><tr><td><a href="./homework.html">Homework</a></td><td>Core and stretch, with the deliverables checklist (must read)</td></tr><tr><td><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-02.html" target="_blank" rel="noreferrer">Slides</a></td><td>The 15-minute concept talk, and the slides for Studio B&#39;s short framings</td></tr><tr><td><a href="./../../templates/PROMPTS.html">PROMPTS.md template</a></td><td>Copied into your repository in Studio A</td></tr><tr><td><a href="./../01-hello-vibe-coding/prompt-starters.html">Week 1 prompt starters</a></td><td>Customization, fixing and three-habits prompts</td></tr></tbody></table><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you are working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>. The <a href="./../../resources/self-paced.html">self-paced path</a> says what to do instead of the pair and class activities.</p><h3 id="from-your-screen-to-the-world" tabindex="-1">From your screen to the world <a class="header-anchor" href="#from-your-screen-to-the-world" aria-label="Permalink to &quot;From your screen to the world&quot;">​</a></h3><p>GitHub stores your files in a <a href="./../../resources/glossary.html#repository"><strong>repository</strong></a> (a project folder that git tracks), and <a href="./../../resources/glossary.html#github-pages"><strong>GitHub Pages</strong></a> serves them as a website, for free. A repository named exactly <code>[your-username].github.io</code> becomes the site at that <a href="./../../resources/glossary.html#url">URL</a> (web address). The file must be called <code>index.html</code>: that&#39;s what a web server sends for a site&#39;s front door. It&#39;s a <a href="./../../resources/glossary.html#static-site"><strong>static site</strong></a>: the server sends the same files to everyone and runs none of your code (servers that run code come in week 9).</p><h3 id="a-commit-is-a-save-point" tabindex="-1">A commit is a save point <a class="header-anchor" href="#a-commit-is-a-save-point" aria-label="Permalink to &quot;A commit is a save point&quot;">​</a></h3><p>Every time you add or edit a file on GitHub, you make a <a href="./../../resources/glossary.html#commit"><strong>commit</strong></a>: a saved snapshot with a message saying what changed (&quot;Add Projects section&quot;, not &quot;update&quot;). The repository keeps every commit, so you can see the history and get old versions back. In week 3 you learn git properly.</p><h3 id="public-means-public" tabindex="-1">Public means public <a class="header-anchor" href="#public-means-public" aria-label="Permalink to &quot;Public means public&quot;">​</a></h3><p>Search engines find your page, and old commits stay visible after you delete something. First name or nickname only; no contact details, student ID or anything about other people. Graded personal writing goes on Canvas, never in a repository (<a href="./../../assessment/#privacy-of-your-work">Privacy of your work</a>).</p><h3 id="the-three-habits" tabindex="-1">The three habits <a class="header-anchor" href="#the-three-habits" aria-label="Permalink to &quot;The three habits&quot;">​</a></h3><p>Students in a Fall 2026 AI-coding course at Carnegie Mellon named these as their most useful practices (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU 15-113 report</a>). You practice all three in Studio B and use them for the rest of the course.</p><ol><li><strong>Ask me questions first.</strong> Before the AI builds, have it ask you what it needs to know. Otherwise it fills the gaps with guesses.</li><li><strong>Show, don&#39;t describe.</strong> A quick sketch or a screenshot with the problem circled says more than a paragraph.</li><li><strong>Say what works before asking for a change.</strong> Name what must stay the same, so the AI doesn&#39;t &quot;improve&quot; it away.</li></ol><h3 id="accessible-from-the-start" tabindex="-1">Accessible from the start <a class="header-anchor" href="#accessible-from-the-start" aria-label="Permalink to &quot;Accessible from the start&quot;">​</a></h3><p><a href="./../../resources/glossary.html#accessibility">Accessibility</a> means people who use a screen reader, a keyboard, zoom or high contrast can use your page too. Most problems on a one-file page take a minute to fix: a missing <code>lang</code> attribute, a clickable <code>&lt;div&gt;</code> that should be a <code>&lt;button&gt;</code>, gray text on gray. You check keyboard, zoom, contrast and structure, ask the AI for a review, and confirm each problem it names yourself.</p><h3 id="promptsmd-how-you-used-ai" tabindex="-1"><code>PROMPTS.md</code>: how you used AI <a class="header-anchor" href="#promptsmd-how-you-used-ai" aria-label="Permalink to &quot;`PROMPTS.md`: how you used AI&quot;">​</a></h3><p>Every project keeps a <a href="./../../resources/glossary.html#promptsmd">Glossary: PROMPTS.md</a> log: the prompts that mattered, what happened, and what you checked. Its <strong>Ownership statement</strong>, written with the AI off, says what you wrote or decided yourself. With Gemini&#39;s Keep Activity off, a closed chat is gone, so copy prompts in as you go. The file is public: no keys, nothing personal.</p><h3 id="your-own-ai-use-rules" tabindex="-1">Your own AI-use rules <a class="header-anchor" href="#your-own-ai-use-rules" aria-label="Permalink to &quot;Your own AI-use rules&quot;">​</a></h3><p>The course&#39;s labels say where AI is allowed; inside them, you decide how <em>you</em> want to use it. Students who had written their own rules for using AI did better than those who hadn&#39;t (<a href="https://arxiv.org/abs/2609.16784" target="_blank" rel="noreferrer">Azimi, 2026</a>). You write version 1 in Studio B with the AI off, and revise it in week 16.</p><h3 id="ai-fluency" tabindex="-1">AI fluency <a class="header-anchor" href="#ai-fluency" aria-label="Permalink to &quot;AI fluency&quot;">​</a></h3><p>You finish the AI Fluency course this week. Its four skills are <strong>Delegation</strong> (what to hand to an AI), <strong>Description</strong> (saying clearly what you want), <strong>Discernment</strong> (judging what comes back) and <strong>Diligence</strong> (taking responsibility for the result). The three habits are Description and Discernment in practice.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><p>At the end of Studio B you complete the Week 2 exit ticket with 🔴 AI off. One question asks you, <strong>from memory</strong>, about a change you made by hand in week 1: which part of the code, and what it did. The others ask how your file became a web page, which habit changed your result, and what your accessibility check found. It&#39;s scored for completion, not correctness.</p><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>About 5 hours, including project time; details on the <a href="./homework.html">homework page</a>. Add a <strong>Projects</strong> section that will link to next week&#39;s game, plus three more improvements, one commit each, using each habit and one change by hand (🔴 AI off) · fix your accessibility list · finish the AI Fluency course and write a short response on Canvas (🔴 AI off) · <code>PROMPTS.md</code> with 5+ entries · a reflection on Canvas (🔴 AI off).</p><p>Graded on effort and completion of the core tier (<a href="./../../assessment/rubrics.html#assignments">rubric</a>).</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>GitHub or Pages is slow or down</td><td>Check <a href="https://www.githubstatus.com" target="_blank" rel="noreferrer">githubstatus.com</a>. Keep your <code>index.html</code> safe on your computer, do the Studio B parts on the saved file, and publish later</td></tr><tr><td>You can&#39;t sign in to GitHub (no phone for the second factor)</td><td>Use one of the recovery codes you saved in week 0. No codes? Do the Studio B parts on your saved file and publish at home</td></tr><tr><td>Gemini is down or blocked</td><td>Use a fallback from the <a href="./../../TOOLS.html">Tool Handout</a>, and paste in your current code first</td></tr><tr><td>You hit a usage limit</td><td>Switch to the next tool in the row. See <a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a></td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>GitHub Docs, <a href="https://docs.github.com/en/pages/quickstart" target="_blank" rel="noreferrer">Quickstart for GitHub Pages</a>.</li><li>W3C, <a href="https://www.w3.org/WAI/test-evaluate/easy-checks/" target="_blank" rel="noreferrer">Easy Checks: a first review of web accessibility</a>.</li><li>More videos, readings and free courses: the <a href="./../../resources/reading-list.html">Reading List</a>.</li></ul>',41)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
